wikiPage.body:
&lt;div class=&quot;presentation navmenu&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Acc&#232;s rapide aux tableaux r&#233;capitulatifs des dons&lt;a class=&quot;headeranchor&quot; id=&quot;Acc&#232;s_rapide_aux_tableaux_r&#233;capitulatifs_des_dons_0&quot; href=&quot;#Acc&#232;s_rapide_aux_tableaux_r&#233;capitulatifs_des_dons_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;table&gt;&lt;tr style=&quot;vertical-align: top; text-align: left&quot;&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Dons.html&quot; title=&quot;Tableau r&#233;capitulatif des dons&quot;&gt;Dons g&#233;n&#233;raux&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Dons-Mythiques.html&quot; title=&quot;Dons mythiques&quot;&gt;Dons mythiques&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-Daudace-Et-De-Panache.html&quot; title=&quot;Dons d&amp;#39;audace et de panache&quot;&gt;Dons d&#39;audace et de panache&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Combat.html&quot; title=&quot;Dons de combat&quot;&gt;Dons de combat&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Cr&#233;ation-Dobjets.html&quot; title=&quot;Dons de cr&#233;ation d&amp;#39;objets&quot;&gt;Dons de cr&#233;ation d&#39;objets&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Critique.html&quot; title=&quot;Dons de critique&quot;&gt;Dons de critique&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-D&#233;cole.html&quot; title=&quot;Dons d&amp;#39;&#233;cole&quot;&gt;Dons d&#39;&#233;cole&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-D&#233;quipe.html&quot; title=&quot;Dons d&amp;#39;&#233;quipe&quot;&gt;Dons d&#39;&#233;quipe&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Ma&#238;trise-Darme.html&quot; title=&quot;Dons de ma&#238;trise d&amp;#39;arme&quot;&gt;Dons de ma&#238;trise d&#39;arme&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Ma&#238;trise-Darmure.html&quot; title=&quot;Dons de ma&#238;trise d&amp;#39;armure&quot;&gt;d&#39;armure&lt;/a&gt;,&lt;br /&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Ma&#238;trise-De-Bouclier.html&quot; title=&quot;Dons de ma&#238;trise de bouclier&quot;&gt;de bouclier&lt;/a&gt;, et &lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Ma&#238;trise-Dobjets.html&quot; title=&quot;Dons de ma&#238;trise d&amp;#39;objet&quot;&gt;d&#39;objet&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Mal&#233;fice-Sanglant.html&quot; title=&quot;Dons de mal&#233;fice sanglant&quot;&gt;Dons de mal&#233;fice sanglant&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-M&#233;tamagie.html&quot; title=&quot;Dons de m&#233;tamagie&quot;&gt;Dons de m&#233;tamagie&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Regard.html&quot; title=&quot;dons de regard&quot;&gt;Dons de regard&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-R&#233;ussite.html&quot; title=&quot;Dons de r&#233;ussite&quot;&gt;Dons de r&#233;ussite&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Spectacle.html&quot; title=&quot;Dons de spectacle&quot;&gt;Dons de spectacle&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-Dalignement.html&quot; title=&quot;Dons d&amp;#39;alignement&quot;&gt;Dons d&#39;alignement (PU)&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-Dhistoire.html&quot; title=&quot;Dons d&amp;#39;histoire&quot;&gt;Dons d&#39;histoire (GC)&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-&#201;sot&#233;riques.html&quot; title=&quot;Dons &#233;sot&#233;riques&quot;&gt;Dons &#233;sot&#233;riques (PU)&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;&lt;ul&gt;
    &lt;li&gt;R&#232;gles g&#233;n&#233;rales&lt;/li&gt;
    &lt;ul&gt;
        &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#DESCRIPTION&quot; title=&quot;Les dons&quot;&gt;format&lt;/a&gt;&lt;/li&gt;
        &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#TYPES&quot; title=&quot;Les dons&quot;&gt;types de dons&lt;/a&gt;&lt;/li&gt;
    &lt;/ul&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;i&gt;Certaines aptitudes ne d&#233;pendent pas de la &lt;a class=&quot;pagelink&quot; href=&quot;Races.html&quot; title=&quot;race&quot;&gt;race&lt;/a&gt; du personnage ni de sa &lt;a class=&quot;pagelink&quot; href=&quot;Classes.html&quot; title=&quot;classe&quot;&gt;classe&lt;/a&gt; ou de ses &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences.html&quot; title=&quot;Les comp&#233;tences&quot;&gt;comp&#233;tences&lt;/a&gt;. Il s’agit plut&#244;t de r&#233;flexes particuli&#232;rement vifs qui permettent au personnage de r&#233;agir plus rapidement face au danger, de sa capacit&#233; &#224; cr&#233;er des objets magiques, de son entra&#238;nement &#224; manier les armes de m&#234;l&#233;e de fa&#231;on &#224; porter des coups tr&#232;s puissants ou d’un talent pour d&#233;vier les projectiles.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;Ces aptitudes sont regroup&#233;es sous le terme de &#171; dons &#187;. Certains sont plus utiles &#224; certaines classes qu’&#224; d’autres et, pour beaucoup, il faut remplir certaines conditions avant de les utiliser, mais, en r&#232;gle g&#233;n&#233;rale, les dons repr&#233;sentent des aptitudes qui n’entrent pas dans le cadre de la race ou de la classe du personnage.&lt;br /&gt;&lt;br /&gt;De nombreux dons modifient ou am&#233;liorent les capacit&#233;s de classe ou att&#233;nuent les restrictions qu’elles imposent tandis que d’autres offrent des bonus aux statistiques du personnage ou lui permettent d’entreprendre une action qui devrait lui &#234;tre interdite.&lt;br /&gt;&lt;br /&gt;En s&#233;lectionnant les dons de son personnage, tout au long de sa &lt;a class=&quot;pagelink&quot; href=&quot;Progression-Des-Personnages.html&quot; title=&quot;Progression des personnages&quot;&gt;progression&lt;/a&gt;, un joueur peut donc le personnaliser et l’adapter &#224; ses besoins.&lt;br /&gt;&lt;br /&gt;Les personnages peuvent acqu&#233;rir un don &#224; chaque niveau impair. Certaines races et certaines classes b&#233;n&#233;ficient de la possibilit&#233; d&#39;obtenir des dons suppl&#233;mentaires. Cela est alors pr&#233;cis&#233; dans leur description. Ces dons s&#39;ajoutent &#224; ceux obtenus du fait de la progression du personnage.&lt;br /&gt;&lt;br /&gt;&lt;div style=&quot;background-color: #fff; float: right; padding: 0 0 12px 12px&quot;&gt;&lt;table id=&quot;TocContainerTable&quot;&gt;&lt;tr&gt;&lt;td&gt;&lt;div id=&quot;TocContainer&quot;&gt;&lt;p class=&quot;small&quot;&gt;&lt;b&gt;Table of Contents&lt;/b&gt;&lt;span id=&quot;ExpandTocSpan&quot;&gt; [&lt;a href=&quot;#&quot; onclick=&quot;javascript:if(document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]==&#39;none&#39;) document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;&#39;; else document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;none&#39;; return false;&quot;&gt;Hide/Show&lt;/a&gt;]&lt;/span&gt;&lt;/p&gt;&lt;div id=&quot;Toc&quot;&gt;&lt;p&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Conditions_16&quot;&gt; Conditions &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Types_de_dons_17&quot;&gt; Types de dons &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Don_d’alignement_0&quot;&gt;Don d’alignement&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Don_d’audace_1&quot;&gt; Don d’audace &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Don_de_panache_2&quot;&gt; Don de panache &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Dons_de_combat_3&quot;&gt; Dons de combat &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Dons_de_critique_4&quot;&gt; Dons de critique &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Dons_de_cr&#233;ation_d’objets_5&quot;&gt; Dons de cr&#233;ation d’objets &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Dons_de_ma&#238;trise_darme_6&quot;&gt;Dons de ma&#238;trise d&#39;arme&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Dons_de_ma&#238;trise_darmure_7&quot;&gt;Dons de ma&#238;trise d&#39;armure&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Dons_de_ma&#238;trise_de_bouclier_8&quot;&gt;Dons de ma&#238;trise de bouclier&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Dons_de_ma&#238;trise_dobjets_9&quot;&gt;Dons de ma&#238;trise d&#39;objets&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Dons_de_mal&#233;fice_sanglant_10&quot;&gt;Dons de mal&#233;fice sanglant&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Dons_de_m&#233;tamagie_11&quot;&gt; Dons de m&#233;tamagie &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Dons_d&#233;quipe_12&quot;&gt; Dons d&#39;&#233;quipe &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Dons_de_regard_13&quot;&gt; Dons de regard &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Dons_de_spectacle_14&quot;&gt; Dons de spectacle &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Dons_d&#233;cole_15&quot;&gt; Dons d&#39;&#233;cole &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Description_des_dons_18&quot;&gt;Description des dons&lt;/a&gt;&lt;br /&gt;&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;CONDITIONS&quot; href=&quot;#CONDITIONS&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt; Conditions &lt;a class=&quot;headeranchor&quot; id=&quot;Conditions_16&quot; href=&quot;#Conditions_16&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Certains dons souscrivent &#224; une ou plusieurs conditions. Un personnage doit disposer de la valeur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques.html&quot; title=&quot;caract&#233;ristique&quot;&gt;caract&#233;ristique&lt;/a&gt;, l’aptitude de classe, le don, la &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences.html&quot; title=&quot;Les comp&#233;tences&quot;&gt;comp&#233;tence&lt;/a&gt;, le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;bonus de base &#224; l’attaque&lt;/a&gt; ou toute autre qualit&#233; indiqu&#233;e pour avoir le droit de choisir et d’utiliser le don qui l’int&#233;resse. Un personnage peut choisir un don une fois qu’il a atteint le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; qui lui permet de remplir les conditions donn&#233;es.&lt;br /&gt;&lt;br /&gt;Un personnage ne peut pas continuer &#224; utiliser un don lorsqu’il ne satisfait plus &#224; l’ensemble des conditions pr&#233;alables. En revanche, il ne perd pas son don : si, par la suite, il en remplit &#224; nouveau les conditions d’utilisation, il pourra de nouveau se servir du don.&lt;br /&gt;&lt;br /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - Classes avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Class Guide/Manuel des joueurs - Classes avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMCA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;En ce qui concerne les conditions requises par un don, un personnage disposant du pouvoir de classe de panache remplit les m&#234;mes conditions que s’il utilisait l’audace et vice versa. Vis-&#224;-vis des dons, des objets magiques et autres effets, un utilisateur de panache d&#233;pense et gagne des points de panache au lieu de points d’audace et inversement.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;TYPES&quot; href=&quot;#TYPES&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt; Types de dons &lt;a class=&quot;headeranchor&quot; id=&quot;Types_de_dons_17&quot; href=&quot;#Types_de_dons_17&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Certains dons sont d’ordre g&#233;n&#233;ral, ce qui signifie qu’aucune r&#232;gle particuli&#232;re ne s’adresse &#224; eux. D’autres permettent aux lanceurs de sorts de cr&#233;er divers types d’objets magiques. Les dons de m&#233;tamagie permettent &#224; un jeteur de sorts de pr&#233;parer et lancer un sort aux effets sup&#233;rieurs, en utilisant un &lt;a class=&quot;pagelink&quot; href=&quot;Emplacement-De-Sort.html&quot; title=&quot;emplacement de sort&quot;&gt;emplacement de sort&lt;/a&gt; de plus haut niveau.&lt;br /&gt;&lt;br /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Pathfinder unchained (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Pathfinder unchained&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoPU.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;DONALIGNEMENT&quot; href=&quot;#DONALIGNEMENT&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Don d’alignement&lt;a class=&quot;headeranchor&quot; id=&quot;Don_d’alignement_0&quot; href=&quot;#Don_d’alignement_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Si un personnage poss&#232;de au moins 10 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Desdevie.html&quot; title=&quot;DV&quot;&gt;DV&lt;/a&gt;, il a acc&#232;s aux dons correspondant &#224; son alignement. Il ne peut avoir qu’un seul don d’alignement &#224; la fois mais, s’il change d’alignement, il peut &#233;changer son ancien don d’alignement contre un autre d&#232;s qu’il gagne un niveau de personnage. La plupart des dons d’alignement ont une entr&#233;e baptis&#233;e R&#233;sidu qui repr&#233;sente le maigre avantage que le personnage conserve s’il ne poss&#232;de plus l’alignement correspondant &#224; son don, ce qui peut l’aider &#224; retrouver son ancien alignement. De nombreux dons d’alignement permettent de stocker des affirmations en vue d’une utilisation ult&#233;rieure. Si le personnage change d’alignement et ne peut plus stocker les &lt;a class=&quot;pagelink&quot; href=&quot;Alignement-Unchained.html#Glissements_et_affirmations_2&quot; title=&quot;L&amp;#39;alignement unchained&quot;&gt;affirmations&lt;/a&gt;, il perd toutes celles qu’il avait en r&#233;serve.  
Voir la &lt;a class=&quot;pagelink&quot; href=&quot;Dons-Dalignement.html&quot; title=&quot;Dons d&amp;#39;alignement&quot;&gt;liste des dons d&#39;alignement&lt;/a&gt;&lt;br /&gt;&lt;br /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;DONAUDACE&quot; href=&quot;#DONAUDACE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt; Don d’audace &lt;a class=&quot;headeranchor&quot; id=&quot;Don_d’audace_1&quot; href=&quot;#Don_d’audace_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un don d’audace interagit avec l’audace du &lt;a class=&quot;pagelink&quot; href=&quot;Pistolier.html&quot; title=&quot;Le pistolier&quot;&gt;pistolier&lt;/a&gt;, avec celle d’un pouvoir de classe ou avec celle qui d&#233;coule du don &lt;a class=&quot;pagelink&quot; href=&quot;Pistolier-Amateur.html&quot; title=&quot;Pistolier amateur&quot;&gt;Pistolier amateur&lt;/a&gt;. Il &#233;largit g&#233;n&#233;ralement l’&#233;ventail d’exploits. Parfois, ces dons augmentent le nombre de points d’audace du personnage ou modifient sa mani&#232;re de les r&#233;cup&#233;rer. Un pistolier peut choisir un don d’audace comme don suppl&#233;mentaire.  
Voir la &lt;a class=&quot;pagelink&quot; href=&quot;Dons-Daudace-Et-De-Panache.html&quot; title=&quot;Dons d&amp;#39;audace et de panache&quot;&gt;liste des dons d&#39;audace&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - Classes avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Class Guide/Manuel des joueurs - Classes avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMCA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;DONPANACHE&quot; href=&quot;#DONPANACHE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt; Don de panache &lt;a class=&quot;headeranchor&quot; id=&quot;Don_de_panache_2&quot; href=&quot;#Don_de_panache_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les dons de panache agissent sur le pouvoir de classe du &lt;a class=&quot;pagelink&quot; href=&quot;Bretteur.html&quot; title=&quot;Le bretteur&quot;&gt;bretteur&lt;/a&gt; panache ou sur le panache qu’apporte le don &lt;a class=&quot;pagelink&quot; href=&quot;Bretteur-Amateur.html&quot; title=&quot;Bretteur amateur&quot;&gt;Bretteur amateur&lt;/a&gt;. Les bretteurs peuvent prendre des dons de panache comme dons suppl&#233;mentaires.  
Voir la &lt;a class=&quot;pagelink&quot; href=&quot;Dons-Daudace-Et-De-Panache.html&quot; title=&quot;Dons d&amp;#39;audace et de panache&quot;&gt;liste des dons de panache&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;DONCOMBAT&quot; href=&quot;#DONCOMBAT&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;COMBAT&quot; href=&quot;#COMBAT&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt; Dons de combat &lt;a class=&quot;headeranchor&quot; id=&quot;Dons_de_combat_3&quot; href=&quot;#Dons_de_combat_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les &lt;a class=&quot;pagelink&quot; href=&quot;Lutteur.html&quot; title=&quot;Le lutteur&quot;&gt;lutteurs&lt;/a&gt;, les &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html&quot; title=&quot;Le guerrier&quot;&gt;guerriers&lt;/a&gt;, les &lt;a class=&quot;pagelink&quot; href=&quot;Pistolier.html&quot; title=&quot;Le pistolier&quot;&gt;pistoliers&lt;/a&gt;, les &lt;a class=&quot;pagelink&quot; href=&quot;Bretteur.html&quot; title=&quot;Le bretteur&quot;&gt;bretteurs&lt;/a&gt; et les
&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre-Combattant.html&quot; title=&quot;Le pr&#234;tre combattant&quot;&gt;pr&#234;tres combattants&lt;/a&gt; peuvent choisir des dons de combat comme dons suppl&#233;mentaires. Les autres classes peuvent prendre des dons de combat &#224; condition de remplir les conditions requises.  
Voir la &lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Combat.html&quot; title=&quot;Dons de combat&quot;&gt;liste des dons de combat&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;DONCRITIQUE&quot; href=&quot;#DONCRITIQUE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;CRITIQUE&quot; href=&quot;#CRITIQUE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt; Dons de critique &lt;a class=&quot;headeranchor&quot; id=&quot;Dons_de_critique_4&quot; href=&quot;#Dons_de_critique_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les dons de critique modifient les effets des &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Coupcritique.html&quot; title=&quot;coup critique&quot;&gt;coups critiques&lt;/a&gt; en infligeant une condition n&#233;gative suppl&#233;mentaire aux victimes. Les personnages qui ne disposent pas du don &lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;trise-Du-Critique.html&quot; title=&quot;Ma&#238;trise du critique&quot;&gt;Ma&#238;trise du critique&lt;/a&gt; appliquent un effet de don de critique au maximum quand ils infligent un &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Coupcritique.html&quot; title=&quot;coup critique&quot;&gt;coup critique&lt;/a&gt;. Les personnages qui disposent de plusieurs dons de critique choisissent celui qu’ils souhaitent appliquer une fois le critique confirm&#233;.  
Voir la &lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Critique.html&quot; title=&quot;Dons de critique&quot;&gt;liste des dons de critique&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;DONCREATION&quot; href=&quot;#DONCREATION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;CREATION&quot; href=&quot;#CREATION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt; Dons de cr&#233;ation d’objets &lt;a class=&quot;headeranchor&quot; id=&quot;Dons_de_cr&#233;ation_d’objets_5&quot; href=&quot;#Dons_de_cr&#233;ation_d’objets_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;div style=&quot;float:right; padding-left: 6px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Manuel-Des-Joueurs-(Dons-Et-Comp&#233;tences).html#12&quot; title=&quot;FAQ du Manuel des joueurs, section dons et comp&#233;tences&quot;&gt;→&lt;/a&gt; Dons de cr&#233;ation d’objet : Avoir un niveau de lanceur de sort par un pouvoir magique remplit-il le pr&#233;requis de NLS des dons de cr&#233;ation d’objet ?&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;Non. &lt;i&gt;(Retour &#224; la &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#DONCREATION&quot; title=&quot;Les dons&quot;&gt;r&#232;gle&lt;/a&gt;&lt;/u&gt;)&lt;/i&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:50px; cursor:pointer&quot; src=&quot;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&quot; title=&quot;Cliquez pour afficher/cacher une FAQ officielle relative &#224; ce texte&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
